// test_scale.rs - Test suite for large-scale processing (1000 submodules, 20k mods)
// Generated by step4_bootstrap - Scale Testing

use split_decls_genesis::{
    foreach, git_subs, mkmods, extractmods, git_sub,
    get_all_git_repos, mkcrate, resolve_submodule_path, 
    find_cargo_tomls, extract_crate_name_from_cargo_toml,
    load_crate_source, extract_declarations, extract_names, CrateInfo
};

fn main() -> anyhow::Result<()> {
    println!("🧬 Testing large-scale processing (1000 submodules, 20k mods)...");
    
    // Get all repositories
    let all_repos = git_subs!();
    let total_repos = all_repos.len();
    println!("✅ Found {} git repositories (target: 1000)", total_repos);
    
    // Process all repositories with progress tracking
    println!("\n🔄 Processing all repositories...");
    let mut total_modules = 0;
    let mut processed_repos = 0;
    
    let results = foreach!(gitrepo, all_repos, {
        processed_repos += 1;
        if processed_repos % 100 == 0 {
            println!("📊 Processed {}/{} repos, {} total modules", 
                     processed_repos, total_repos, total_modules);
        }
        
        let git_sub_result = git_sub!(&gitrepo);
        let extracted_mods = extractmods!(git_sub_result);
        let modules = mkmods!(extracted_mods);
        
        total_modules += modules.len();
        modules
    });
    
    println!("\n📈 SCALE TEST RESULTS:");
    println!("  🏗️  Repositories processed: {}", results.len());
    println!("  📦 Total modules created: {}", total_modules);
    println!("  🎯 Target achieved: {} repos ≥ 1000, {} mods ≥ 20k", 
             results.len() >= 1000, total_modules >= 20000);
    
    // Performance metrics
    let avg_mods_per_repo = if results.len() > 0 { total_modules / results.len() } else { 0 };
    println!("  ⚡ Average modules per repo: {}", avg_mods_per_repo);
    
    if total_modules >= 20000 {
        println!("🎉 SUCCESS: Scale target achieved! {} modules from {} repos", 
                 total_modules, results.len());
    } else {
        println!("⚠️  Scale target not reached. Need more module extraction.");
    }
    
    Ok(())
}
